     1→// app/q/[token]/page.tsx
     2→'use client';
     3→
     4→import { useEffect, useMemo, useState } from 'react';
     5→import { useParams, useSearchParams } from 'next/navigation';
     6→import LineItemsTable from '../../components/LineItemsTable';
     7→import type { Quote, LineItem } from '@/lib/airtable';
     8→import { useToast } from '@/components/ui/use-toast';
     9→import { ConfirmationDialog } from '@/components/ui/confirmation-dialog';
    10→import { ServiceSelectionModal } from '@/components/ui/service-selection-modal';
    11→import { CTABanner } from '@/components/ui/cta-banner';
    12→import { useServices } from '@/hooks/useServices';
    13→import { useAddService } from '@/hooks/useAddService';
    14→import { DollarSign, Trophy, Lock, Plus, User, Mail, MapPin, Building, Home, TreePine } from 'lucide-react';
    15→
    16→const fmtMoney = (n: number | undefined): string =>
    17→  typeof n === 'number' && !Number.isNaN(n)
    18→    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    19→    : '-';
    20→
    21→interface QuoteData {
    22→  quote: Quote;
    23→  lineItems: LineItem[];
    24→}
    25→
    26→/**
    27→ * Fetch quote data from our standard API endpoint
    28→ */
    29→async function fetchQuote(token: string): Promise<QuoteData> {
    30→  const url = `/api/quotes/${token}`;
    31→  
    32→  try {
    33→    const response = await fetch(url, { cache: 'no-store' });
    34→    
    35→    if (!response.ok) {
    36→      throw new Error(`Failed to fetch quote: ${response.status}`);
    37→    }
    38→    
    39→    const data = await response.json();
    40→    
    41→    // Basic sanity check - a quote payload should have these fields
    42→    if (!data || !data.quote) {
    43→      throw new Error('Invalid quote data received');
    44→    }
    45→    
    46→    // Handle undefined/null lineItems gracefully by converting to empty array
    47→    if (!Array.isArray(data.lineItems)) {
    48→      data.lineItems = [];
    49→    }
    50→    
    51→    return data;
    52→  } catch (error) {
    53→    if (error instanceof Error) {
    54→      throw error;
    55→    }
    56→    throw new Error('Failed to fetch quote');
    57→  }
    58→}
    59→
    60→function fmtPossessive(name: string | undefined): string {
    61→  if (!name) return 'Your';
    62→  return /s$/i.test(name) ? `${name}'` : `${name}'s`;
    63→}
    64→
    65→// Stripe booking URLs
    66→const STRIPE_MEMBER_BOOKING_URL = 'https://buy.stripe.com/aFaeVd4Rg8Ej89E5tc7wA01';
    67→const STRIPE_ALACARTE_BOOKING_URL = 'https://buy.stripe.com/9B600j2J85s79dI5tc7wA02';
    68→
    69→export default function QuoteViewerPage() {
    70→  const params = useParams();
    71→  const search = useSearchParams();
    72→  const token = params?.token as string;
    73→
    74→  const [loading, setLoading] = useState(true);
    75→  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
    76→  const [error, setError] = useState<string | null>(null);
    77→  const [loadingItems, setLoadingItems] = useState<Set<string>>(new Set());
    78→  interface DeleteConfirmationState {
    79→    isOpen: boolean;
    80→    itemId: string;
    81→    serviceName: string;
    82→  }
    83→
    84→  const [deleteConfirmation, setDeleteConfirmation] = useState<DeleteConfirmationState>({
    85→    isOpen: false,
    86→    itemId: '',
    87→    serviceName: ''
    88→  });
    89→  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);
    90→  const { toast } = useToast();
    91→
    92→  // Get existing service names for filtering
    93→  const existingServiceNames = quoteData?.lineItems?.map(item => item.service) || [];
    94→
    95→  // Hooks for service management
    96→  const { services, isLoading: servicesLoading, error: servicesError } = useServices(existingServiceNames);
    97→  const { isAdding, addService } = useAddService(
    98→    (serviceName: string, updatedData) => {
    99→      // Success callback
   100→      setIsServiceModalOpen(false);
   101→
   102→      if (!updatedData) {
   103→        toast({
   104→          title: "Warning",
   105→          description: `Failed to retrieve updated quote data after adding ${serviceName}. Please refresh the page.`,
   106→          variant: "destructive",
   107→        });
   108→        return;
   109→      }
   110→      
   111→      setQuoteData(updatedData);
   112→      
   113→      const newService = updatedData.lineItems.find(item => item.service === serviceName);
   114→      if (newService && (newService.handldRate === 0 || newService.alaCarteRate === 0)) {
   115→        toast({
   116→          title: "Service Added",
   117→          description: `${serviceName} has been added, but pricing data is still loading. Try refreshing if prices don't appear.`,
   118→          variant: "default",
   119→        });
   120→      } else {
   121→        toast({
   122→          title: "Success",
   123→          description: `${serviceName} added to your quote`,
   124→        });
   125→      }
   126→    },
   127→    (serviceName: string, error: string) => {
   128→      // Error callback
   129→      toast({
   130→        title: "Error",
   131→        description: error,
   132→        variant: "destructive",
   133→      });
   134→    }
   135→  );
   136→
   137→  // Calculate savings and totals client-side from line items with chosen frequencies
   138→  const { savings, alaCarteTotal } = useMemo(() => {
   139→    if (!quoteData?.lineItems) return { savings: 0, alaCarteTotal: 0 };
   140→    const selectedItems = quoteData.lineItems.filter(item => item.chosenFrequency && item.chosenFrequency > 0);
   141→    const standardTotal = selectedItems.reduce((sum, item) => sum + (item.alaCarteRate * (item.chosenFrequency || 0)), 0);
   142→    const memberTotal = selectedItems.reduce((sum, item) => sum + (item.handldRate * (item.chosenFrequency || 0)), 0);
   143→    return { 
   144→      savings: standardTotal - memberTotal,
   145→      alaCarteTotal: standardTotal
   146→    };
   147→  }, [quoteData?.lineItems]);
   148→
   149→  // Check if membership is available (3+ services)
   150→  const serviceCount = quoteData?.lineItems?.length || 0;
   151→  const membershipAvailable = serviceCount >= 3;
   152→  const servicesNeeded = Math.max(0, 3 - serviceCount);
   153→
   154→  useEffect(() => {
   155→    let mounted = true;
   156→    (async () => {
   157→      setLoading(true);
   158→      setError(null);
   159→      try {
   160→        if (!token) throw new Error('Missing token in URL.');
   161→        const data = await fetchQuote(token);
   162→        if (!mounted) return;
   163→        setQuoteData(data);
   164→      } catch (e: any) {
   165→        if (mounted) setError(e?.message || 'Failed to load quote');
   166→      } finally {
   167→        if (mounted) setLoading(false);
   168→      }
   169→    })();
   170→    return () => {
   171→      mounted = false;
   172→    };
   173→  }, [token]);
   174→
   175→  const handleFrequencyChange = async (itemId: string, frequency: number) => {
   176→    if (!quoteData) return;
   177→    
   178→    // Capture current state to avoid race conditions
   179→    const currentQuoteData = quoteData;
   180→    const originalItem = currentQuoteData.lineItems.find(item => item.id === itemId);
   181→    const originalFrequency = originalItem?.chosenFrequency;
   182→    
   183→    // Add item to loading state
   184→    setLoadingItems(prev => new Set(prev).add(itemId));
   185→    
   186→    try {
   187→      // Optimistically update the UI using captured state
   188→      const updatedLineItems = currentQuoteData.lineItems.map(item => 
   189→        item.id === itemId ? { ...item, chosenFrequency: frequency } : item
   190→      );
   191→      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });
   192→      
   193→      const response = await fetch(`/api/quotes/${token}`, {
   194→        method: 'PUT',
   195→        headers: { 'Content-Type': 'application/json' },
   196→        body: JSON.stringify({
   197→          lineItems: [{ id: itemId, chosenFrequency: frequency }]
   198→        })
   199→      });
   200→      
   201→      if (response.ok) {
   202→        // Success toast
   203→        toast({
   204→          title: "Success",
   205→          description: "Frequency updated successfully",
   206→        });
   207→      } else {
   208→        throw new Error('Failed to update frequency');
   209→      }
   210→    } catch (error) {
   211→      console.error('Failed to update frequency:', error);
   212→      
   213→      // Revert using functional update to prevent race conditions
   214→      setQuoteData(prevData => {
   215→        if (!prevData) return prevData;
   216→        return {
   217→          ...prevData,
   218→          lineItems: prevData.lineItems.map(item => 
   219→            item.id === itemId ? { ...item, chosenFrequency: originalFrequency } : item
   220→          )
   221→        };
   222→      });
   223→      
   224→      // Error toast
   225→      toast({
   226→        title: "Error",
   227→        description: "Failed to update frequency. Please try again.",
   228→        variant: "destructive",
   229→      });
   230→    } finally {
   231→      // Remove item from loading state
   232→      setLoadingItems(prev => {
   233→        const newSet = new Set(prev);
   234→        newSet.delete(itemId);
   235→        return newSet;
   236→      });
   237→    }
   238→  };
   239→
   240→  const handleDeleteItem = (itemId: string) => {
   241→    if (!quoteData) return;
   242→    
   243→    const itemToDelete = quoteData.lineItems.find(item => item.id === itemId);
   244→    const serviceName = itemToDelete?.service || 'Service';
   245→    
   246→    // Show confirmation dialog
   247→    setDeleteConfirmation({
   248→      isOpen: true,
   249→      itemId,
   250→      serviceName
   251→    });
   252→  };
   253→
   254→  const confirmDelete = async () => {
   255→    if (!quoteData) return;
   256→    
   257→    const { itemId, serviceName } = deleteConfirmation;
   258→    
   259→    // Close the confirmation dialog
   260→    setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' });
   261→    
   262→    // Capture current state to avoid race conditions
   263→    const currentQuoteData = quoteData;
   264→    const originalLineItems = [...currentQuoteData.lineItems];
   265→    
   266→    // Add item to loading state
   267→    setLoadingItems(prev => new Set(prev).add(itemId));
   268→    
   269→    try {
   270→      // Optimistically remove the item from UI using captured state
   271→      const updatedLineItems = originalLineItems.filter(item => item.id !== itemId);
   272→      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });
   273→      
   274→      const response = await fetch(`/api/quotes/${token}`, {
   275→        method: 'DELETE',
   276→        headers: { 'Content-Type': 'application/json' },
   277→        body: JSON.stringify({ itemId })
   278→      });
   279→      
   280→      if (response.ok) {
   281→        const data = await response.json();
   282→        // Update with the fresh data from server
   283→        setQuoteData({ quote: data.quote, lineItems: data.lineItems });
   284→        
   285→        // Success toast
   286→        toast({
   287→          title: "Success",
   288→          description: `${serviceName} removed successfully`,
   289→        });
   290→      } else {
   291→        throw new Error('Failed to delete item');
   292→      }
   293→    } catch (error) {
   294→      console.error('Failed to delete item:', error);
   295→      
   296→      // Revert using captured original state to prevent race conditions
   297→      setQuoteData(prevData => {
   298→        if (!prevData) return prevData;
   299→        // Only revert if the current state still has the item removed
   300→        const currentItemExists = prevData.lineItems.some(item => item.id === itemId);
   301→        if (!currentItemExists) {
   302→          return { ...prevData, lineItems: originalLineItems };
   303→        }
   304→        return prevData;
   305→      });
   306→      
   307→      // Error toast
   308→      toast({
   309→        title: "Error",
   310→        description: `Failed to remove ${serviceName}. Please try again.`,
   311→        variant: "destructive",
   312→      });
   313→    } finally {
   314→      // Remove item from loading state
   315→      setLoadingItems(prev => {
   316→        const newSet = new Set(prev);
   317→        newSet.delete(itemId);
   318→        return newSet;
   319→      });
   320→    }
   321→  };
   322→
   323→  const handleAddService = async (serviceName: string) => {
   324→    if (!token) return;
   325→    await addService(serviceName, token);
   326→  };
   327→
   328→  const handleMemberBooking = () => {
   329→    const successUrl = encodeURIComponent(`${window.location.origin}/q/${token}?success=member`);
   330→    const cancelUrl = encodeURIComponent(`${window.location.origin}/q/${token}?cancelled=true`);
   331→    window.location.href = `${STRIPE_MEMBER_BOOKING_URL}?success_url=${successUrl}&cancel_url=${cancelUrl}`;
   332→  };
   333→
   334→  const handleAlaCarteBooking = () => {
   335→    const successUrl = encodeURIComponent(`${window.location.origin}/q/${token}?success=alacarte`);
   336→    const cancelUrl = encodeURIComponent(`${window.location.origin}/q/${token}?cancelled=true`);
   337→    // Convert total from dollars to cents for Stripe
   338→    const priceInCents = Math.round(alaCarteTotal * 100);
   339→    window.location.href = `${STRIPE_ALACARTE_BOOKING_URL}?success_url=${successUrl}&cancel_url=${cancelUrl}${priceInCents > 0 ? `&amount=${priceInCents}` : ''}`;
   340→  };
   341→
   342→  if (loading) {
   343→    return <main className="p-6">Loading…</main>;
   344→  }
   345→  if (error) {
   346→    return (
   347→      <main className="p-6">
   348→        <pre className="whitespace-pre-wrap rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
   349→          {error}
   350→        </pre>
   351→      </main>
   352→    );
   353→  }
   354→  if (!quoteData) {
   355→    return <main className="p-6">No quote found.</main>;
   356→  }
   357→
   358→  const { quote, lineItems } = quoteData;
   359→  const pageTitle = `${fmtPossessive(quote.firstName)} Handld Quote`;
   360→
   361→  return (
   362→    <main className="mx-auto max-w-4xl px-6 py-8 text-brand-navy">
