   525→            onClick={handleAlaCarteBooking}
   526→            disabled={alaCarteTotal === 0}
   527→            className={`flex-1 rounded-full py-4 px-8 text-lg font-medium border-2 transition-all duration-200 ${
   528→              alaCarteTotal > 0
   529→                ? 'border-brand-navy text-brand-navy bg-brand-light-cream hover:bg-brand-cream cursor-pointer'
   530→                : 'border-gray-300 text-gray-400 bg-gray-100 cursor-not-allowed opacity-60'
