   546→        onConfirm={confirmDelete}
   547→        onCancel={() => setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' })}
   548→      />
   549→
   550→      {/* Service Selection Modal */}
   551→      <ServiceSelectionModal
