'use client';

import { Loader2 } from 'lucide-react';

interface LoadingScreenProps {
  message?: string;
}

export function LoadingScreen({ message = "Loading your quote..." }: LoadingScreenProps) {
  return (
    <div className="min-h-screen flex items-center justify-center bg-brand-cream">
      <div className="flex flex-col items-center space-y-6">
        {/* Logo with blue spinner around it */}
        <div className="relative">
          {/* Brand navy spinner ring around logo */}
          <div className="absolute inset-0 w-32 h-32 rounded-full border-4 border-brand-navy/30"></div>
          <div className="absolute inset-0 w-32 h-32 rounded-full border-4 border-transparent border-t-brand-navy animate-spin"></div>

          {/* Logo in center */}
          <div className="relative w-32 h-32 flex items-center justify-center">
            <img 
              src="/logo.png" 
              alt="Handld" 
              className="w-20 h-20 object-contain"
            />
          </div>
        </div>

        {/* Loading message */}
        <div className="text-center">
          <p className="text-brand-navy text-lg font-medium">{message}</p>
        </div>
      </div>
    </div>
  );
}

