                  className="w-12 border border-gray-300 rounded-lg px-2 py-1 text-sm bg-white text-brand-navy text-center disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {[...Array(12)].map((_, i) => (
                    <option key={i + 1} value={i + 1}>
                      {i + 1}
                    </option>
                  ))}
                </select>
              </div>
              <div className="text-right font-medium">{fmtMoney(item.alaCarteRate)}</div>
              <div className="text-right font-medium">{fmtMoney(item.handldRate)}</div>
              <div className="text-center">
                <button
                  onClick={() => handleRemoveItem(item.id, item.service)}
                  disabled={isLoading}
                  className="text-red-600 hover:text-red-800 text-sm px-2 py-1 rounded border border-red-300 hover:border-red-500 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>
        );
      })}

    </div>
  );
}

