      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('No services available')).toBeInTheDocument();
      });

      // Should show the close button
      expect(screen.getByText('Close')).toBeInTheDocument();
    });

    it('should update available services after successfully adding a service', async () => {
      const user = userEvent.setup();
      const allServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing'];

      // Initial quote with one service
      const initialQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 100,
          handldTotal: 70,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      // Updated quote after adding service
      const updatedQuoteData = {
        ...initialQuoteData,
        lineItems: [
          ...initialQuoteData.lineItems,
          {
            id: 'rec789',
            service: 'Gutter Cleaning',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      setupStatefulFetchMocks(initialQuoteData, updatedQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal first time
      let addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show Gutter Cleaning and Pressure Washing, but not Window Washing
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Add Gutter Cleaning
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Wait for modal to close and service to be added
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      });

      // Verify Gutter Cleaning now appears in the line items
      await waitFor(() => {
        expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      });

      // Open modal again
      addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Now should only show Pressure Washing (Window Washing and Gutter Cleaning should be filtered out)
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Check specifically within the modal
      const modalContainer = document.querySelector('.fixed.inset-0.z-50');
      if (modalContainer) {
        const modalServiceButtons = modalContainer.querySelectorAll('button span.font-medium.text-brand-navy');
        const modalServices = Array.from(modalServiceButtons).map(btn => btn.textContent);

        expect(modalServices).toContain('Pressure Washing');
        expect(modalServices).not.toContain('Window Washing');
        expect(modalServices).not.toContain('Gutter Cleaning');
      } else {
        throw new Error('Modal container not found on second opening');
      }
    });

    it('should handle case-insensitive service matching correctly', async () => {
      const allServices = ['Window Washing', 'window washing', 'WINDOW WASHING'];

      // Mock quote with one variation
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 100,
          handldTotal: 70,
        },
        lineItems: [
