            id: 'rec456',
            service: 'Window Washing', // Exact case match
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      // Wait for modal to open by checking for the modal dialog
      await waitFor(() => {
        expect(screen.getByRole('dialog')).toBeInTheDocument();
      });

      // With case-insensitive filtering, all variations should be filtered out
      // So the modal should show "No services available"
      await waitFor(() => {
        expect(screen.getByText('No services available')).toBeInTheDocument();
      });

      // None of the service variations should be available since they all match the existing service (case-insensitive)
      expect(screen.queryByText('window washing')).not.toBeInTheDocument();
      expect(screen.queryByText('WINDOW WASHING')).not.toBeInTheDocument();
      // Original case should only be in the main table, not the modal
      const windowWashingButtons = screen.queryAllByText('Window Washing');
      expect(windowWashingButtons.length).toBe(1);
    });
  });

  describe('Edge Cases', () => {
    it('should handle empty line items correctly', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

