// test-setup.ts - Common test mocks and setup for quote page tests

import React from 'react';

// Mock Next.js navigation
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

// Mock the Toaster component
jest.mock('@/components/ui/use-toast', () => ({
  useToast: () => ({
    toast: jest.fn(),
  }),
}));

// Mock CTABanner component
jest.mock('@/components/ui/cta-banner', () => ({
  CTABanner: ({ message }: { message: string }) => (
    React.createElement('div', { 'data-testid': 'cta-banner' }, message)
  ),
}));

// Mock WelcomeBanner component
jest.mock('@/components/ui/welcome-banner', () => ({
  WelcomeBanner: () => (
    React.createElement('div', { 'data-testid': 'welcome-banner' }, 'Welcome! This is your personalized quote...')
  ),
}));

// Mock LoadingScreen component
jest.mock('@/components/ui/loading-screen', () => ({
  LoadingScreen: ({ message }: { message?: string }) => (
    React.createElement('div', { 'data-testid': 'loading-screen' }, message || 'Loading...')
  ),
}));

// Mock Logo component
jest.mock('@/components/ui/logo', () => ({
  Logo: ({ size }: { size?: number }) => (
    React.createElement('div', { 'data-testid': 'logo', 'data-size': size }, 'Handld Logo')
  ),
}));

// Common Lucide React icon mocks
export const commonLucideMocks = {
  DollarSign: () => React.createElement('div', { 'data-testid': 'dollar-icon' }, '$'),
  Trophy: () => React.createElement('div', { 'data-testid': 'trophy-icon' }, '🏆'),
  Lock: () => React.createElement('div', { 'data-testid': 'lock-icon' }, '🔒'),
  Plus: () => React.createElement('div', { 'data-testid': 'plus-icon' }, '+'),
  User: () => React.createElement('div', { 'data-testid': 'user-icon' }, '👤'),
  Mail: () => React.createElement('div', { 'data-testid': 'mail-icon' }, '📧'),
  MapPin: () => React.createElement('div', { 'data-testid': 'map-icon' }, '📍'),
  Building: () => React.createElement('div', { 'data-testid': 'building-icon' }, '🏢'),
  Home: () => React.createElement('div', { 'data-testid': 'home-icon' }, '🏠'),
  TreePine: () => React.createElement('div', { 'data-testid': 'tree-icon' }, '🌲'),
  Loader2: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'loader', className }, 'Loading...')
  ),
  X: () => React.createElement('div', { 'data-testid': 'close-icon' }, 'X'),
  Info: () => React.createElement('div', { 'data-testid': 'info-icon' }, 'ℹ'),
  // Service icons
  Droplets: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'droplets-icon', className }, '💧')
  ),
  Sparkles: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'sparkles-icon', className }, '✨')
  ),
  Trash2: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'trash-icon', className }, '🗑️')
  ),
};

// Apply the Lucide React mocks
jest.mock('lucide-react', () => commonLucideMocks);

// Mock fetch
global.fetch = jest.fn();

