      '/api/quotes/test-token',
      {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineItems: [{ id: 'rec1', chosenFrequency: 3 }],
        }),
      }
    );
