import React from 'react';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useParams, useSearchParams } from 'next/navigation';
import { setupFetchMocks, setupStatefulFetchMocks } from '../test-helpers';
import { within } from '@testing-library/react';
import './test-setup';

// Additional service-specific icon mocks
jest.mock('lucide-react', () => ({
  DollarSign: () => React.createElement('div', { 'data-testid': 'dollar-icon' }, '$'),
  Trophy: () => React.createElement('div', { 'data-testid': 'trophy-icon' }, '🏆'),
  Lock: () => React.createElement('div', { 'data-testid': 'lock-icon' }, '🔒'),
  Plus: () => React.createElement('div', { 'data-testid': 'plus-icon' }, '+'),
  User: () => React.createElement('div', { 'data-testid': 'user-icon' }, '👤'),
  Mail: () => React.createElement('div', { 'data-testid': 'mail-icon' }, '📧'),
  MapPin: () => React.createElement('div', { 'data-testid': 'map-icon' }, '📍'),
  Building: () => React.createElement('div', { 'data-testid': 'building-icon' }, '🏢'),
  Home: () => React.createElement('div', { 'data-testid': 'home-icon' }, '🏠'),
  TreePine: () => React.createElement('div', { 'data-testid': 'tree-icon' }, '🌲'),
  Loader2: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'loader', className }, 'Loading...')
  ),
  X: () => React.createElement('div', { 'data-testid': 'close-icon' }, 'X'),
  Info: () => React.createElement('div', { 'data-testid': 'info-icon' }, 'ℹ'),
  Droplets: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'droplets-icon', className }, '💧')
  ),
  Sparkles: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'sparkles-icon', className }, '✨')
  ),
  Trash2: ({ className }: { className?: string }) => (
    React.createElement('div', { 'data-testid': 'trash-icon', className }, '🗑️')
  ),
  Scissors: ({ className }: { className?: string }) => (
    <div data-testid="scissors-icon" className={className}>✂️</div>
  ),
  Waves: ({ className }: { className?: string }) => (
    <div data-testid="waves-icon" className={className}>🌊</div>
  ),
  Wrench: ({ className }: { className?: string }) => (
    <div data-testid="wrench-icon" className={className}>🔧</div>
  ),
  Hammer: ({ className }: { className?: string }) => (
    <div data-testid="hammer-icon" className={className}>🔨</div>
  ),
  Car: ({ className }: { className?: string }) => (
    <div data-testid="car-icon" className={className}>🚗</div>
  ),
  Leaf: ({ className }: { className?: string }) => (
    <div data-testid="leaf-icon" className={className}>🍃</div>
  ),
  Shovel: ({ className }: { className?: string }) => (
    <div data-testid="shovel-icon" className={className}>🔨</div>
  ),
  Zap: ({ className }: { className?: string }) => (
    <div data-testid="zap-icon" className={className}>⚡</div>
  ),
}));

// Mock data
const mockQuoteData = {
  quote: {
    id: 'rec123',
    quoteId: 'Q-001',
    token: 'test-token',
    firstName: 'John',
    lastName: 'Doe',
    email: 'john@example.com',
    city: 'Test City',
    alaCarteTotal: 200,
    handldTotal: 140,
  },
  lineItems: [
    {
      id: 'rec456',
      service: 'Window Washing',
      handldRate: 70,
      alaCarteRate: 100,
      chosenFrequency: 4,
      quoteId: 'Q-001',
    },
  ],
};

const mockServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing - Driveway & Patio'];

describe('Add Service Integration', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockFetch.mockReset();

    // Mock navigation hooks
    (useParams as jest.Mock).mockReturnValue({ token: 'test-token' });
    (useSearchParams as jest.Mock).mockReturnValue({
      get: jest.fn().mockReturnValue(null),
    });

    // Set up basic fetch mocks for quote and services
    setupFetchMocks(mockQuoteData, mockServices);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Add Service Modal Flow', () => {
    it('should open service selection modal when Add Service button is clicked', async () => {
      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Click Add Service button
      const addServiceButton = screen.getByText('Add Service');
      await userEvent.click(addServiceButton);

      // Modal should open
      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should display available services in the modal, excluding existing ones
      const modal = screen.getByRole('dialog');
      const availableServices = mockServices.filter(service => service !== 'Window Washing');
      availableServices.forEach(service => {
        expect(within(modal).getByText(service)).toBeInTheDocument();
      });

      // 'Window Washing' should NOT be available in the modal since it's already in the quote
      expect(within(modal).queryByText('Window Washing')).not.toBeInTheDocument();
    });

    it('should close modal when close button is clicked', async () => {
      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      await userEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Close modal
      const closeButton = screen.getByTestId('close-icon');
      await userEvent.click(closeButton);

      // Modal should close
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      });
    });

    it('should add service successfully and update line items', async () => {
      const user = userEvent.setup();

      // Create updated quote data for after service is added
      const updatedQuoteData = {
        ...mockQuoteData,
        lineItems: [
          ...mockQuoteData.lineItems,
          {
            id: 'rec789',
            service: 'Gutter Cleaning',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      // Setup stateful mocking for this test
      setupStatefulFetchMocks(mockQuoteData, updatedQuoteData, mockServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Initially only one service
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.queryByText('Gutter Cleaning')).not.toBeInTheDocument();

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Select a service
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Wait for service to be added and modal to close
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      });

      // Verify API calls
      expect(mockFetch).toHaveBeenCalledWith('/api/quotes/test-token/items', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          serviceName: 'Gutter Cleaning',
        }),
      });

      expect(mockFetch).toHaveBeenCalledWith('/api/quotes/test-token', {
        cache: 'no-store',
      });

      // New service should appear in the line items
      await waitFor(() => {
        expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      });
    });

    it('should handle service addition error gracefully', async () => {
      const user = userEvent.setup();

      // Mock the add service API call to fail
      mockFetch.mockResolvedValueOnce({
        ok: false,
        status: 500,
        json: async () => ({ error: 'Server error' }),
      });

      // Since this is just testing the add service failure, we don't need to mock retries

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Select a service
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Wait for error handling - modal should close after error
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      }, { timeout: 5000 });

      // Service should not be added to the line items
      expect(screen.queryByText('Gutter Cleaning')).not.toBeInTheDocument();

      // Only original service should remain
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
    });

    it('should show loading state while adding service', async () => {
      const user = userEvent.setup();

      // Mock slow add service API call
      let resolveAddService: (value: any) => void;
      const addServicePromise = new Promise(resolve => {
        resolveAddService = resolve;
      });

      // Reset mockFetch for this test and set up URL-based mocking
      mockFetch.mockReset();
      mockFetch.mockImplementation((url: string, options?: any) => {
        if (url.includes('/api/quotes/') && options?.method === 'POST') {
          // Return the delayed promise for add service POST request
          return addServicePromise;
        } else if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => mockQuoteData,
          });
        } else if (url.includes('/api/services')) {
          return Promise.resolve({
            ok: true,
            json: async () => ({ services: mockServices }),
          });
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Select a service
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Should show loading overlay
      await waitFor(() => {
        expect(screen.getByText('Adding service...')).toBeInTheDocument();
      });

      // Should disable interactions
      const closeButton = screen.getByTestId('close-icon').closest('button')!;
      expect(closeButton).toHaveAttribute('disabled');

      // Resolve the API call
      resolveAddService!({
        ok: true,
        created: { id: 'rec789' },
      });

      // Wait for loading to complete
      await waitFor(() => {
        expect(screen.queryByText('Adding service...')).not.toBeInTheDocument();
      });
    });
  });

  describe('Service Loading States', () => {
    it('should show loading state while fetching services', async () => {
      // Mock slow services fetch
      let resolveServices: (value: any) => void;
      const servicesPromise = new Promise(resolve => {
        resolveServices = resolve;
      });

      // Reset mockFetch for this test and set up URL-based mocking
      mockFetch.mockReset();
      mockFetch.mockImplementation((url: string) => {
