      // Mock slow services fetch
      let resolveServices: (value: any) => void;
      const servicesPromise = new Promise(resolve => {
        resolveServices = resolve;
      });

      // Reset mockFetch for this test and set up URL-based mocking
      mockFetch.mockReset();
      mockFetch.mockImplementation((url: string) => {
        if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => mockQuoteData,
          });
        } else if (url.includes('/api/services')) {
          // Return the delayed promise for services
          return servicesPromise.then(() => Promise.resolve({
            ok: true,
            json: async () => ({ services: mockServices }),
          }));
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      await userEvent.click(addServiceButton);

      // Should show loading state
      await waitFor(() => {
        expect(screen.getByText('Loading services...')).toBeInTheDocument();
      });

      // Resolve services
      resolveServices!({ services: mockServices });

      // Should show services
      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });
    });

    it('should show error state when services fail to load', async () => {
      // Reset mockFetch for this test and set up URL-based mocking
      mockFetch.mockReset();
      mockFetch.mockImplementation((url: string) => {
        if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => mockQuoteData,
          });
        } else if (url.includes('/api/services')) {
          // Return error for services fetch
          return Promise.resolve({
            ok: false,
            status: 500,
          });
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      await userEvent.click(addServiceButton);

      // Should show error state
      await waitFor(() => {
        expect(screen.getByText('Failed to fetch services: 500')).toBeInTheDocument();
      });
    });
  });
});

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useParams, useSearchParams } from 'next/navigation';
import { setupFetchMocks, setupStatefulFetchMocks } from '../test-helpers';
import './setup';

// Test-specific setup
const mockFetch = global.fetch as jest.MockedFunction<typeof fetch>;

describe('Duplicate Service Prevention', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockFetch.mockReset();

    // Mock navigation hooks using the exported mocks from test-setup
    const { mockUseParams, mockUseSearchParams } = require('./setup');
    mockUseParams.mockReturnValue({ token: 'test-token' });
    mockUseSearchParams.mockReturnValue({
      get: jest.fn().mockReturnValue(null),
    });
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Service Filtering Based on Existing Services', () => {
    it('should not show services that are already in the quote', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing', 'Handyman'];
      const existingServices = ['Window Washing', 'Handyman'];
      const availableServices = ['Gutter Cleaning', 'Pressure Washing'];

      // Mock quote data with existing services
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 200,
          handldTotal: 140,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
            service: 'Handyman',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 2,
            quoteId: 'Q-001',
          },
        ],
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Verify existing services are displayed
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Handyman')).toBeInTheDocument();

      // Open the service selection modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should only show available services (not existing ones)
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Should NOT show existing services in the modal - check specifically within the modal
      const modalContainer = document.querySelector('.fixed.inset-0.z-50');
      if (modalContainer) {
        const modalServiceButtons = modalContainer.querySelectorAll('button span.font-medium.text-brand-navy');
        const modalServices = Array.from(modalServiceButtons).map(btn => btn.textContent);

        expect(modalServices).not.toContain('Window Washing');
        expect(modalServices).not.toContain('Handyman');
        expect(modalServices).toContain('Gutter Cleaning');
        expect(modalServices).toContain('Pressure Washing');
      } else {
        throw new Error('Modal container not found');
      }
    });

    it('should show "No services available" when all services are already added', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote data with all available services
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 200,
          handldTotal: 140,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
            service: 'Gutter Cleaning',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open the service selection modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('No services available')).toBeInTheDocument();
      });

      // Should show the close button
      expect(screen.getByText('Close')).toBeInTheDocument();
    });

    it('should update available services after successfully adding a service', async () => {
      const user = userEvent.setup();
      const allServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing'];

      // Initial quote with one service
      const initialQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 100,
          handldTotal: 70,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      // Updated quote after adding service
      const updatedQuoteData = {
        ...initialQuoteData,
        lineItems: [
          ...initialQuoteData.lineItems,
          {
            id: 'rec789',
            service: 'Gutter Cleaning',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      setupStatefulFetchMocks(initialQuoteData, updatedQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal first time
      let addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show Gutter Cleaning and Pressure Washing, but not Window Washing
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Add Gutter Cleaning
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Wait for modal to close and service to be added
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      });

      // Verify Gutter Cleaning now appears in the line items
      await waitFor(() => {
        expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      });

      // Open modal again
      addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Now should only show Pressure Washing (Window Washing and Gutter Cleaning should be filtered out)
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Check specifically within the modal
      const modalContainer = document.querySelector('.fixed.inset-0.z-50');
      if (modalContainer) {
        const modalServiceButtons = modalContainer.querySelectorAll('button span.font-medium.text-brand-navy');
        const modalServices = Array.from(modalServiceButtons).map(btn => btn.textContent);

        expect(modalServices).toContain('Pressure Washing');
        expect(modalServices).not.toContain('Window Washing');
        expect(modalServices).not.toContain('Gutter Cleaning');
      } else {
        throw new Error('Modal container not found on second opening');
      }
    });

    it('should handle case-insensitive service matching correctly', async () => {
      const allServices = ['Window Washing', 'window washing', 'WINDOW WASHING'];

      // Mock quote with one variation
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 100,
          handldTotal: 70,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing', // Exact case match
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
        ],
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      // Wait for modal to open by checking for the modal dialog
      await waitFor(() => {
        expect(screen.getByRole('dialog')).toBeInTheDocument();
      });

      // With case-insensitive filtering, all variations should be filtered out
      // So the modal should show "No services available"
      await waitFor(() => {
        expect(screen.getByText('No services available')).toBeInTheDocument();
      });

      // None of the service variations should be available since they all match the existing service (case-insensitive)
      expect(screen.queryByText('window washing')).not.toBeInTheDocument();
      expect(screen.queryByText('WINDOW WASHING')).not.toBeInTheDocument();
      // Original case should only be in the main table, not the modal
      const windowWashingButtons = screen.queryAllByText('Window Washing');
      expect(windowWashingButtons.length).toBe(1);
    });
  });

  describe('Edge Cases', () => {
    it('should handle empty line items correctly', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote with no line items
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 0,
          handldTotal: 0,
        },
        lineItems: [],
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show all services since none are existing
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
    });

    it('should handle undefined line items correctly', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote with undefined line items
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 0,
          handldTotal: 0,
        },
        lineItems: undefined,
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should show all services since line items is undefined
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
    });
  });
});

