import React from 'react';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import QuoteViewerPage from '../page';
import { useToast } from '@/components/ui/use-toast';
import { setupFetchMocks, setupUpdateFetchMocks, setupErrorFetchMocks, setupDelayedUpdateFetchMocks, setupCustomFetchMock } from '../test-helpers';
import './setup';

// Mock useToast specifically for this test file
jest.mock('@/components/ui/use-toast', () => ({
  useToast: jest.fn(),
}));


// Test-specific mocks (extending common setup)

jest.mock('../../../components/LineItemsTable', () => {
  return function MockLineItemsTable({ 
    lineItems, 
    loadingItems, 
    onFrequencyChange,
    onRemoveItem
  }: any) {
    return (
      <div data-testid="line-items-table">
        {lineItems.map((item: any) => (
          <div key={item.id}>
            <span>{item.service}</span>
            <button 
              onClick={() => onFrequencyChange?.(item.id, 3)}
              disabled={loadingItems?.has(item.id)}
            >
              Change Frequency
            </button>
            <button 
              onClick={() => onRemoveItem?.(item.id)}
              disabled={loadingItems?.has(item.id)}
            >
              Remove
            </button>
            {loadingItems?.has(item.id) && <span>Loading...</span>}
          </div>
        ))}
      </div>
    );
  };
});


describe('QuoteViewerPage - Membership Requirements', () => {
  const mockToast = jest.fn();
  const mockQuoteDataWithTwoServices = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@example.com',
      city: 'San Francisco',
      stories: '2',
      squareFootage: '2000',
      lotSize: 'Medium',
    },
    lineItems: [
      { id: 'line1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
      { id: 'line2', service: 'Service 2', alaCarteRate: 150, handldRate: 105, chosenFrequency: 2 },
    ],
  };

  const mockQuoteDataWithThreeServices = {
    quote: {
      id: 'rec123',
      quoteId: 'Q-001',
      firstName: 'John',
      lastName: 'Doe',
      email: 'john@example.com',
      city: 'San Francisco',
      stories: '2',
      squareFootage: '2000',
      lotSize: 'Medium',
    },
    lineItems: [
      { id: 'line1', service: 'Service 1', alaCarteRate: 100, handldRate: 70, chosenFrequency: 1 },
      { id: 'line2', service: 'Service 2', alaCarteRate: 150, handldRate: 105, chosenFrequency: 2 },
      { id: 'line3', service: 'Service 3', alaCarteRate: 200, handldRate: 140, chosenFrequency: 1 },
    ],
  };

  beforeEach(() => {
    jest.clearAllMocks();
    (useToast as jest.Mock).mockReturnValue({ toast: mockToast });
    const { mockUseParams, mockUseSearchParams } = require('./setup');
    mockUseParams.mockReturnValue({ token: 'test-token' });
    mockUseSearchParams.mockReturnValue({ get: () => null });
  });

  describe('CTA Banner and Membership Button', () => {
    it('should show CTA banner and disable membership button with less than 3 services', async () => {
      setupFetchMocks(mockQuoteDataWithTwoServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // Check CTA banner is shown with dynamic message
        const ctaBanner = screen.getByTestId('cta-banner');
        expect(ctaBanner).toBeInTheDocument();
        expect(ctaBanner).toHaveTextContent('Add 1 more service to unlock Handld Membership and save 30%!');

        // Check membership button is disabled with informative text
        const membershipButton = screen.getByText('Membership requires 3+ services');
        expect(membershipButton).toBeDisabled();
        expect(membershipButton).toHaveClass('cursor-not-allowed');
        expect(membershipButton).toHaveClass('opacity-60');

        // Check Add Service button exists (no special styling when < 3 services)
        const addServiceButton = screen.getByText('Add Service');
        expect(addServiceButton.closest('button')).toBeInTheDocument();
      });
    });

    it('should hide CTA banner and enable membership button with 3 or more services', async () => {
      setupFetchMocks(mockQuoteDataWithThreeServices);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // Check CTA banner is NOT shown
        expect(screen.queryByTestId('cta-banner')).not.toBeInTheDocument();

        // Check membership button is enabled
        const membershipButton = screen.getByText(/Book Handld Membership/);
        expect(membershipButton).not.toBeDisabled();
        expect(membershipButton).toHaveClass('cursor-pointer');
        expect(membershipButton).not.toHaveClass('opacity-60');

        // Check Add Service button exists (no special styling when >= 3 services)
        const addServiceButton = screen.getByText('Add Service');
        expect(addServiceButton.closest('button')).toBeInTheDocument();

        // Check savings display is shown and CTA banner is hidden
        expect(screen.queryByTestId('cta-banner')).not.toBeInTheDocument();
      });
    });

    it('should show correct messaging for single service needed', async () => {
      const oneServiceData = {
        ...mockQuoteDataWithThreeServices,
        lineItems: mockQuoteDataWithThreeServices.lineItems.slice(0, 2),
      };

      setupFetchMocks(oneServiceData);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // CTA banner should be present
        expect(screen.getByTestId('cta-banner')).toBeInTheDocument();
      });
    });

    it('should show correct messaging for multiple services needed', async () => {
      const noServiceData = {
        ...mockQuoteDataWithThreeServices,
        lineItems: [],
      };

      setupFetchMocks(noServiceData);

      render(<QuoteViewerPage />);

      await waitFor(() => {
        // CTA banner should be present
        expect(screen.getByTestId('cta-banner')).toBeInTheDocument();
      });
    });
  });
});

