          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 200,
          handldTotal: 140,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 4,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
            service: 'Handyman',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 2,
            quoteId: 'Q-001',
