'use client';

import React from 'react';
import { Sparkles } from 'lucide-react';

interface CTABannerProps {
  message: string;
  className?: string;
}

export function CTABanner({ message, className = '' }: CTABannerProps) {
  return (
    <div className={`relative overflow-hidden bg-gradient-to-r from-yellow-400 via-orange-400 to-red-400 rounded-xl p-5 shadow-xl ${className}`}>
      <div className="absolute inset-0 bg-gradient-to-r from-yellow-400/20 via-orange-400/20 to-red-400/20 animate-pulse"></div>
      <div className="relative flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Sparkles className="h-8 w-8 text-white filter drop-shadow-md" />
