        redirected: false,
        statusText: 'Internal Server Error',
        type: 'basic',
        url: '',
        clone: jest.fn(),
        body: null,
        bodyUsed: false,
        arrayBuffer: jest.fn(),
        blob: jest.fn(),
        formData: jest.fn(),
        text: jest.fn(),
        json: async () => ({ error: 'Server error' }),
      } as Response);

      // Since this is just testing the add service failure, we don't need to mock retries

      render(<QuoteViewerPage />);

