      const addServiceButton = screen.getByText('Add Service');
      await user.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Select a service
      const gutterCleaningButton = screen.getByText('Gutter Cleaning');
      await user.click(gutterCleaningButton);

      // Wait for service to be added and modal to close
      await waitFor(() => {
        expect(screen.queryByText('Select a service to add to your quote:')).not.toBeInTheDocument();
      });

      // Verify API calls
      expect(mockFetch).toHaveBeenCalledWith('/api/quotes/test-token/items', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          serviceName: 'Gutter Cleaning',
        }),
      });

      expect(mockFetch).toHaveBeenCalledWith('/api/quotes/test-token', {
        cache: 'no-store',
      });

      // New service should appear in the line items
      await waitFor(() => {
        expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      });
    });

